from pathlib import Path
import importlib.util
p=Path(__file__).resolve().parents[1];spec=importlib.util.spec_from_file_location('pages',p/'tools/build_pages.py');g=importlib.util.module_from_spec(spec);spec.loader.exec_module(g)
nav='<nav class="d-flex flex-wrap gap-3 mb-4"><a href="jquery.html">Іздеу</a><a href="jquery-ux.html">Кино клубы</a><a href="jquery-tools.html">Постерлер мен бөлісу</a></nav>'
bodies={
'jquery.html':(p/'data/catalogue.tpl').read_text(),
'jquery-ux.html':'''<h1 class="page-title">Кино клубының жаңалықтары</h1><p>Кино әлеміндегі таңдаулар мен жеке ұсыныстар.</p><section class="card mb-4"><div class="card-body d-flex gap-5 flex-wrap"><p><strong class="jq-counter fs-2" data-target="34">0</strong><br>Туынды</p><p><strong class="jq-counter fs-2" data-target="22">0</strong><br>Жанр</p><p><strong class="jq-counter fs-2" data-target="9">0</strong><br>Апталық таңдау</p></div></section><form id="jqForm" class="card p-4 mb-5"><h2 class="h4">Ұсыныс жіберу</h2><p>Оқу демосы: хабарлама серверге жіберілмейді.</p><label for="jqName">Атыңыз</label><input id="jqName" data-rule="name" class="form-control mb-3" required minlength="2" maxlength="60"><label for="jqMessage">Қандай кино ұсынасыз?</label><textarea id="jqMessage" class="form-control mb-3" required maxlength="500"></textarea><button id="jqSubmit" type="submit" class="btn btn-danger">Жіберу</button><p id="jqFormStatus" class="mt-3" role="status"></p></form><div id="jqReading"></div>''',
'jquery-tools.html':'''<h1 class="page-title">Постерлер мен бөлісу</h1><section class="card p-4 mb-4"><h2 class="h5">Достарыңызбен бөлісіңіз</h2><p id="jqShare">67Films — кино кешіне жаңа идея: https://symbtmn.github.io/67films/</p><button id="jqCopy" type="button" class="btn btn-outline-danger align-self-start" aria-describedby="jqCopyTip">Көшіру</button><span id="jqCopyTip" class="jq-tooltip" role="tooltip" hidden>Көшірілді!</span><label for="jqWatchMovie" class="form-label mt-4">Көру тізіміне кино таңдаңыз</label><select id="jqWatchMovie" class="form-select"></select><p id="jqSavedCount" class="small mt-2" role="status"></p><ul id="jqSavedList"></ul><button id="jqNotify" type="button" class="btn btn-outline-secondary mt-3 align-self-start">Тізімге қосу</button></section><div id="jqLazyGrid" class="row row-cols-2 row-cols-md-3 g-4"></div>'''}
for file,body in bodies.items():
 g.page(p,file,'Кино клубы / jQuery',nav+body,True)
 f=p/file;s=f.read_text().replace('</head>','''<script src="https://code.jquery.com/jquery-4.0.0.min.js"></script><script src="js/jquery-fallback.js"></script><script src="js/jquery-assignment.js?v=final-1" defer></script><link rel="stylesheet" href="css/jquery-assignment.css?v=final-1"></head>''').replace('<body>','<body><div id="jqProgress" role="progressbar" aria-label="Оқу барысы" aria-valuemin="0" aria-valuemax="100" aria-valuenow="0"></div><div id="jqToast" role="status" aria-live="polite" hidden></div>');f.write_text(s)
